files["arcane-knowledge.js"]="/* Shared website facts and page content. Generated by scripts/build-pages.cjs. */\n(function(){\nconst knowledge="+JSON.stringify(knowledge,null,2)+";\nif(typeof module!=='undefined'&&module.exports)module.exports=knowledge;else window.ArcaneKnowledge=knowledge;\n})();\n";
files["sitemap.xml"]='<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+pages.map(p=>"  <url><loc>"+base+p.url+"</loc></url>").join("\n")+"\n</urlset>\n";
