const knowledge=require('../arcane-knowledge.js');const copy=JSON.parse(fs.readFileSync(path.join(root,'content/site-copy.json'),'utf8'));const navbar=fs.readFileSync(path.join(root,'templates/navbar.html'),'utf8').trim();const template=fs.readFileSync(path.join(root,'templates/site.html'),'utf8').replace('<!-- SHARED_NAVBAR -->',navbar);
const files=generatePages(knowledge,copy,template);for(const [name,content]of Object.entries(files)){const destination=path.join(root,name);fs.mkdirSync(path.dirname(destination),{recursive:true});fs.writeFileSync(destination,content);}
